def first_at_or_after(timestamps, since):
    """Index of the first entry of the sorted list `timestamps` that is >= `since`; len(timestamps) if there is none."""
    lo, hi = 0, len(timestamps)
    for _ in range(64):          # a correct search needs about log2(n) steps; 64 covers any list that fits in memory
        if lo >= hi:
            return lo
