def first_at_or_after(timestamps, since):
    lo, hi = 0, len(timestamps)
    for _ in range(64):
        if lo >= hi:
            return lo
        mid = (lo + hi) // 2
        if timestamps[mid] < since:
            lo = mid + 1             # timestamps[mid] is too old, so the answer is after it
        else:
            hi = mid                 # timestamps[mid] could be the answer: keep it inside the range
    raise RuntimeError("binary search did not converge")
